def maximumValue(strs):
    max_value = 0

    for s in strs:
        # Assume by default string has only digits
        is_digit = True
        for c in s:
            if not c.isdigit():
                is_digit = False
                break

        if is_digit:
            # If string is only digits, convert to int (handles leading zeroes)
            val = int(s)
        else:
            # If contains any letter, value is length of s
            val = len(s)

        if val > max_value:
            max_value = val

    return max_value
